import{_ as i,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Ceph Performance Meeting 2019-01-03","description":"","frontmatter":{"title":"Ceph Performance Meeting 2019-01-03","date":"2019-01-03T00:00:00.000Z","updated":"2019-01-04T00:00:00.000Z","tags":["Ceph","分布式存储","OSD 设计","Sharding","跨核心通信"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_Performance_Meeting_2019-01-03.md","filePath":"posts/2019/Ceph_Performance_Meeting_2019-01-03.md","lastUpdated":1780459816000}'),o={name:"posts/2019/Ceph_Performance_Meeting_2019-01-03.md"};function n(a,e,s,p,_,g){return l(),t("div",null,[...e[0]||(e[0]=[r("<p>本次会议主要讨论了 Ceph 分布式存储系统的性能优化和开发议题，涵盖以下关键内容：</p><p><strong>关键议题</strong>：</p><ol><li><p><strong>NUMA 节点状态监控</strong>：</p><ul><li>讨论在 NUMA 节点上添加基础设施，以监控连接的 NUMA 节点，并在对象存储后端和 NIC 上进行相同操作。</li><li>讨论添加新的命令或状态，以报告 OSD 的 NUMA 节点状态，并提供可视化工具。</li><li>讨论重写关于前端和后端网络的老旧文档，并强调将两个 NIC 都放在前端网络上的重要性。</li></ul></li><li><p><strong>OSD 设计和性能</strong>：</p><ul><li>讨论了 OSD 设计的两种方法：简单 OSD（单线程）和更强大的 OSD（多线程）。</li><li>讨论了使用 SPDK 或 QAT 等技术提高性能和减少对内核的依赖。</li><li>讨论了数据放置决策，以及是否应该更多地依赖本地 NUMA 节点内的快速查找而不是 Crush 算法。</li></ul></li><li><p><strong>Sharding 和跨核心通信</strong>：</p><ul><li>讨论了 Sharding 在系统中的应用，以及如何处理跨核心通信和共享资源。</li><li>讨论了使用共享指针和消息传递来实现跨核心数据共享。</li><li>讨论了使用跨核心消息传递层和跨核心交叉开关的复杂性。</li></ul></li></ol><p><strong>决定的事项</strong>：</p><ol><li>将 NUMA 节点状态监控功能添加到开发列表。</li><li>对 OSD 设计进行进一步研究，并考虑使用 SPDK 或 QAT 等技术。</li><li>与硬件制造商合作，了解未来的硬件路线图。</li><li>在下一次 Crimson 核心团队会议中讨论 Sharding 和跨核心通信。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Sage 将更新 PRS 并提供关于 NUMA 节点状态监控的更多详细信息。</li><li>Kieffer 将重写关于前端和后端网络的文档。</li><li>Radek 将与 Crimson 核心团队讨论 OSD 设计和 Sharding。</li><li>Greg 将与硬件制造商合作，了解未来的硬件路线图。</li></ol>",7)])])}const c=i(o,[["render",n]]);export{S as __pageData,c as default};
